package httpserver

import (
	"io"
	"net/http"
)

func renderCostOutsourcingWorkspace(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, costOutsourcingWorkspacePage)
}

func costOutsourcingWorkspaceScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, costOutsourcingWorkspaceJavaScript)
}

const costOutsourcingWorkspacePage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>成本与外协</title><style>` + costOutsourcingWorkspaceCSS + `[hidden]{display:none!important}</style></head><body>
<header class="top"><a class="brand" href="./"><span>CO</span><strong>成本与外协</strong></a><div class="credential"><span id="credentialState">尚未连接</span><button id="openCredential" class="quiet">设置访问凭证</button></div></header>
<div class="layout"><aside class="rail"><p class="eyebrow">C6 业务工作区</p><button class="nav active" data-view="overview">使用说明</button><button class="nav" data-view="workspace">业务记录</button><div class="rail-note"><strong>事实边界</strong><span>本应用拥有已发生成本、外协委托和评估；Project、主体、合同和文件只冻结精确引用与快照。</span></div></aside><main>
<section id="overview" class="view active"><div class="hero"><p class="eyebrow">Cost &amp; Outsourcing</p><h1>把项目成本和外协委托，登记成可核对、可纠正、可追溯的业务事实。</h1><p>按 Project 读取费用或外协。金额、Evidence、纠正、撤回和评估入口都来自服务端 <code>allowed_actions</code>；权限变化后刷新凭证，不沿用旧动作。</p><button class="primary" data-go="workspace">进入业务记录</button></div><div class="flow"><article><b>01</b><h2>选定 Project</h2><p>建立准确的业务范围，不跨项目猜测。</p></article><article><b>02</b><h2>登记事实</h2><p>冻结 Project、主体、合同与 Evidence 的精确版本。</p></article><article><b>03</b><h2>纠正与复盘</h2><p>用 revision 追加纠正、撤回和外协评估。</p></article></div></section>
<section id="workspace" class="view"><div class="section-head"><div><p class="eyebrow">Project 范围</p><h1>成本与外协业务记录</h1></div><button id="newRecord" class="primary" disabled>新建记录</button></div>
<form id="projectForm" class="project-bar"><label>Project ID<input id="projectID" required placeholder="稳定 UUID"></label><button class="quiet" type="submit">读取当前事实</button></form>
<div class="mode-tabs" role="tablist"><button type="button" class="mode active" data-mode="cost">成本录入</button><button type="button" class="mode" data-mode="engagement">外协委托</button><button type="button" class="mode" data-mode="suggestion">应付建议</button></div>
<div id="notice" class="notice">设置访问凭证并输入 Project ID。页面不会把“无权查看”或依赖失败伪装成空数据。</div>
<div class="workspace-grid"><section class="panel"><div class="panel-head"><div><h2 id="listTitle">成本记录</h2><span id="projectContext">尚未选择 Project</span></div><button id="reload" class="quiet" disabled>重新读取</button></div><div id="recordList" class="record-list"><div class="empty"><strong>还没有读取业务事实</strong><span>从上方输入 Project ID 开始。</span></div></div></section>
<aside class="panel detail"><div class="panel-head"><div><h2>详情、历史与恢复</h2><span>选择记录后查看精确快照和 revision。</span></div></div><div id="detail"><div class="empty">选择一条记录。</div></div><div id="historyList" class="timeline"></div></aside></div></section></main></div>
<dialog id="credentialDialog"><form method="dialog" id="credentialForm"><p class="eyebrow">访问控制</p><h2>连接受保护 API</h2><p>本地验证粘贴模板 Token；正式组合由 Gateway 从 IAM 会话换取短期凭证。Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">保存并连接</button></div></form></dialog>
<dialog id="recordDialog"><form method="dialog" id="recordForm"><p class="eyebrow" id="formEyebrow">登记事实</p><h2 id="formTitle">新建成本记录</h2><input name="record_id" type="hidden"><input name="form_mode" type="hidden" value="create"><div class="form-grid">
<label>Project revision<input name="project_revision" type="number" min="1" required></label><label id="costCategoryField">成本类别<select name="category"><option value="vehicle">车辆</option><option value="accommodation">住宿</option><option value="public_transport">公共交通</option><option value="other">其他</option></select></label><label id="costDateField">发生日期<input name="occurred_on" type="date"></label><label>币种<input name="currency" value="CNY" required></label><label>金额（分）<input name="amount_minor" type="number" min="0" required></label><label id="distanceField">里程（米，仅车辆）<input name="distance_meters" type="number" min="0"></label>
<label id="providerIDField" hidden>服务方 Party ID<input name="provider_id"></label><label id="providerRevisionField" hidden>Party revision<input name="provider_revision" type="number" min="1"></label><label id="scopeField" class="wide" hidden>外协范围<textarea name="scope" rows="3"></textarea></label><label id="descriptionField" class="wide">成本说明<textarea name="description" rows="3"></textarea></label><label id="noteField" class="wide" hidden>备注<textarea name="note" rows="2"></textarea></label>
<label id="contractIDField" hidden>可选合同 ID<input name="contract_id"></label><label id="contractRevisionField" hidden>合同 revision<input name="contract_revision" type="number" min="1"></label><label id="reasonField" class="wide" hidden>纠正原因<textarea name="reason" rows="2"></textarea></label></div>
<details><summary>可选：Evidence 精确引用</summary><div class="form-grid advanced"><label>Evidence File ID<input name="evidence_id"></label><label>Version<input name="evidence_version" type="number" min="1"></label><label>槽位<input name="evidence_slot" placeholder="receipt / contract"></label></div></details>
<div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">提交并重新读取</button></div></form></dialog>
<dialog id="assessmentDialog"><form method="dialog" id="assessmentForm"><p class="eyebrow">外协评估</p><h2>追加五分制评估</h2><input name="engagement_id" type="hidden"><input name="engagement_revision" type="hidden"><label>评分（1–5）<input name="score" type="number" min="1" max="5" required></label><label>评估原因<textarea name="reason" rows="3" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">追加评估</button></div></form></dialog>
<dialog id="suggestionDialog"><form method="dialog" id="suggestionForm"><p class="eyebrow">C6 → Money</p><h2>从精确业务 revision 提出应付建议</h2><p>这里只提出建议；Money Flow 独立接受或拒绝，并在接受时拥有最终应付义务。</p><div class="form-grid"><label>来源类型<select name="source_type"><option value="outsourcing_engagement">外协委托</option><option value="cost_entry">成本记录</option></select></label><label>来源 ID<input name="source_id" required></label><label>来源 revision<input name="source_revision" type="number" min="1" required></label><label>本方 Party ID<input name="ledger_owner_id" required></label><label>本方 Party revision<input name="ledger_owner_revision" type="number" min="1" required></label><label>到期日<input name="due_on" type="date" required></label><label class="wide">用途<textarea name="purpose" rows="3" required></textarea></label><label id="suggestionCounterpartyID" hidden>成本相对方 Party ID<input name="counterparty_id"></label><label id="suggestionCounterpartyRevision" hidden>成本相对方 Party revision<input name="counterparty_revision" type="number" min="1"></label></div><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">提出建议</button></div></form></dialog>
<script src="assets/cost-outsourcing.js"></script></body></html>`

const costOutsourcingWorkspaceCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#18212f;background:#f4f6f8;line-height:1.55;--ink:#18212f;--muted:#667085;--line:#dce1e8;--soft:#f7f8fa;--accent:#3157a4;--danger:#a93a33}*{box-sizing:border-box}body{margin:0}.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);text-decoration:none}.brand span{display:grid;place-items:center;width:34px;height:34px;border-radius:7px;background:#243b66;color:#fff;font-size:12px;font-weight:800}.credential{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 64px)}.rail{padding:26px 18px;background:#fff;border-right:1px solid var(--line)}.eyebrow{margin:0 0 9px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{width:100%;padding:11px 13px;border:0;border-left:3px solid transparent;background:transparent;color:#4d596b;text-align:left;font:inherit;cursor:pointer}.nav.active{border-color:var(--accent);background:#edf3fb;color:var(--accent);font-weight:750}.rail-note{display:grid;gap:5px;margin-top:32px;padding:14px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}main{min-width:0;padding:30px}.view{display:none}.view.active{display:block}.hero{min-height:340px;padding:54px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#fff 65%,#eaf0f8)}h1,h2,h3,p{margin-top:0}.hero h1{max-width:820px;margin-bottom:18px;font-size:clamp(34px,5vw,56px);line-height:1.08;letter-spacing:-.04em}.hero>p:not(.eyebrow){max-width:760px;color:var(--muted);font-size:17px}.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.flow article,.panel{border:1px solid var(--line);border-radius:10px;background:#fff}.flow article{padding:22px}.flow b{color:var(--accent)}.flow h2{margin:12px 0 6px;font-size:17px}.flow p{margin:0;color:var(--muted);font-size:13px}.primary,.quiet,.danger,.mode{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet,.mode{border-color:var(--line);background:#fff;color:#3f4a5a}.danger{background:var(--danger);color:#fff}.primary:disabled,.quiet:disabled{opacity:.45;cursor:not-allowed}.section-head,.panel-head,.card-head,.dialog-actions,.mode-tabs{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-head{margin-bottom:16px}.section-head h1{margin:0;font-size:28px}.project-bar{display:grid;grid-template-columns:minmax(280px,620px) auto;gap:10px;align-items:end;padding:14px;border:1px solid var(--line);border-radius:9px;background:#fff}.mode-tabs{justify-content:flex-start;margin:14px 0}.mode.active{border-color:var(--accent);background:#edf3fb;color:var(--accent)}.notice{margin:12px 0;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#922}.workspace-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(360px,1fr);gap:16px}.panel{min-height:540px;padding:18px}.panel-head{padding-bottom:14px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:18px}.panel-head span{color:var(--muted);font-size:12px}.record-list{display:grid;gap:10px;margin-top:14px}.record-card{padding:15px;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:8px;cursor:pointer}.record-card.selected{box-shadow:0 0 0 2px #3157a433}.record-card.withdrawn{border-left-color:var(--danger);background:#fff9f9}.card-head h3{margin:0;font-size:16px}.badges,.actions{display:flex;flex-wrap:wrap;gap:6px}.badge{padding:3px 8px;border-radius:999px;background:#eef1f4;color:#566273;font-size:11px;font-weight:750}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.fact{padding:10px;background:var(--soft);border-radius:6px}.fact small{display:block;color:var(--muted)}.fact strong{font-size:13px}.source{margin:0;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.detail-block{padding:14px 0;border-bottom:1px solid var(--line)}.detail-block h3{margin-bottom:8px;font-size:15px}.empty{display:grid;gap:5px;place-content:center;min-height:180px;color:var(--muted);text-align:center}.timeline{display:grid;gap:9px;margin-top:14px}.event{padding:12px;border-left:3px solid #bdc6d2;background:var(--soft);font-size:12px}.event strong{display:block;color:var(--ink)}label{display:grid;gap:5px;color:#4c5667;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;color:var(--ink);font:inherit;font-size:13px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.wide{grid-column:1/-1}details{margin-top:14px;padding:10px;border:1px solid var(--line);border-radius:7px}summary{cursor:pointer;color:var(--accent);font-size:13px;font-weight:700}.advanced{margin-top:10px}dialog{width:min(760px,calc(100vw - 32px));padding:24px;border:1px solid var(--line);border-radius:11px;box-shadow:0 18px 50px #18212f2a}dialog::backdrop{background:#18212f66}.dialog-actions{margin-top:18px;justify-content:flex-end}@media(max-width:940px){.layout{grid-template-columns:1fr}.rail{display:none}main{padding:18px}.flow,.workspace-grid{grid-template-columns:1fr}.project-bar{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}`

const costOutsourcingWorkspaceJavaScript = `const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],gatewayMode=location.pathname!=='/'&&!location.pathname.startsWith('/assets/'),state={token:sessionStorage.getItem('cost-outsourcing-demo-token')||'',projectID:'',mode:'cost',items:[],collectionActions:[],selected:null};
const A={costCreate:'cost-entry.create',costCorrect:'cost-entry.correct',costWithdraw:'cost-entry.withdraw',costHistory:'cost-entry.history.read',engagementCreate:'outsourcing-engagement.create',engagementCorrect:'outsourcing-engagement.correct',engagementWithdraw:'outsourcing-engagement.withdraw',engagementAssess:'outsourcing-engagement.assess',engagementHistory:'outsourcing-engagement.history.read',suggestionCreate:'outsourcing-payable-suggestion.create',suggestionRead:'outsourcing-payable-suggestion.read',suggestionWithdraw:'outsourcing-payable-suggestion.withdraw'};
function notice(message,kind=''){const n=$('#notice');n.textContent=message;n.className='notice '+kind}function esc(v){const s=document.createElement('span');s.textContent=v??'';return s.innerHTML}function money(v,c='CNY'){return v==null?'金额未授权':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c||'CNY'}).format(v/100)}function can(item,action){return (item?.allowed_actions||[]).includes(action)}
async function api(path,options={}){const headers={Accept:'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};const response=await fetch(path.replace(/^\//,''),{...options,headers});const body=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(body.error?.code||'HTTP_'+response.status);error.status=response.status;error.retryable=body.error?.retryable;throw error}return body}
function setCredential(){state.token=$('#token').value.trim();sessionStorage.setItem('cost-outsourcing-demo-token',state.token);$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接'}
function endpoint(){return state.mode==='cost'?'/api/v1/cost-entries':state.mode==='engagement'?'/api/v1/outsourcing-engagements':'/api/v1/payable-suggestions'}function createAction(){return state.mode==='cost'?A.costCreate:state.mode==='engagement'?A.engagementCreate:A.suggestionCreate}function title(){return state.mode==='cost'?'成本记录':state.mode==='engagement'?'外协委托':'应付建议'}
function render(){const root=$('#recordList');root.replaceChildren();$('#listTitle').textContent=title();$('#newRecord').textContent=state.mode==='cost'?'登记成本':state.mode==='engagement'?'登记外协':'提出应付建议';$('#newRecord').disabled=!state.projectID||!state.collectionActions.includes(createAction());if(!state.items.length){root.innerHTML='<div class="empty"><strong>当前 Project 还没有'+title()+'</strong><span>有权限时可从右上角登记第一条事实。</span></div>';renderDetail();return}for(const item of state.items){const card=document.createElement('article');card.className='record-card '+item.state+(state.selected?.id===item.id?' selected':'');if(state.mode==='suggestion'){card.innerHTML='<div class="card-head"><div><h3>'+esc(item.purpose)+'</h3><div class="badges"><span class="badge">'+esc(item.state)+'</span><span class="badge">C6 r'+item.revision+'</span><span class="badge">Money r'+(item.target_revision||'—')+'</span></div></div><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="facts"><div class="fact"><small>来源</small><strong>'+esc(item.source.type)+' · r'+item.source.revision+'</strong></div><div class="fact"><small>到期日</small><strong>'+esc(item.due_on)+'</strong></div></div><p class="source">ID：'+esc(item.id)+'</p>'}else{const name=state.mode==='cost'?(item.description||item.category):(item.provider?.legal_name||'未命名服务方');const secondary=state.mode==='cost'?item.category:item.scope;card.innerHTML='<div class="card-head"><div><h3>'+esc(name)+'</h3><div class="badges"><span class="badge">'+esc(item.state)+'</span><span class="badge">revision '+item.revision+'</span></div></div><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="facts"><div class="fact"><small>Project</small><strong>'+esc(item.project?.display_name||item.project?.id)+'</strong></div><div class="fact"><small>'+(state.mode==='cost'?'发生日期':'业务范围')+'</small><strong>'+esc(state.mode==='cost'?item.occurred_on:secondary)+'</strong></div></div><p class="source">ID：'+esc(item.id)+'</p>'}card.onclick=()=>{state.selected=item;render();renderDetail()};root.append(card)}}
function renderDetail(){const root=$('#detail');$('#historyList').replaceChildren();const item=state.selected;if(!item){root.innerHTML='<div class="empty">选择一条记录。</div>';return}if(state.mode==='suggestion'){const actions=['<button class="quiet" data-action="history">读取历史</button>'];if(state.collectionActions.includes(A.suggestionCreate))actions.push('<button class="quiet" data-action="synchronize">同步 Money 状态</button>');if(state.collectionActions.includes(A.suggestionWithdraw)&&item.state==='proposed')actions.push('<button class="danger" data-action="suggestion-withdraw">撤回建议</button>');root.innerHTML='<div class="detail-block"><div class="card-head"><div><h3>建议与 Money 决定</h3><div class="badges"><span class="badge">'+esc(item.state)+'</span><span class="badge">C6 r'+item.revision+'</span></div></div><div class="actions">'+actions.join('')+'</div></div></div><div class="detail-block"><h3>冻结来源</h3><p class="source">'+esc(item.source.type)+' '+esc(item.source.id)+' · r'+item.source.revision+'<br>'+esc(item.source.digest)+'</p></div><div class="detail-block"><h3>业务含义</h3><div class="facts"><div class="fact"><small>金额</small><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="fact"><small>到期日</small><strong>'+esc(item.due_on)+'</strong></div></div><p>'+esc(item.purpose)+'</p><p class="source">本方：'+esc(item.ledger_owner.legal_name)+' · r'+item.ledger_owner.revision+'<br>相对方：'+esc(item.counterparty.legal_name)+' · r'+item.counterparty.revision+(item.obligation?'<br>Money Obligation：'+esc(item.obligation.id)+' · r'+item.obligation.revision:'')+(item.decision_reason?'<br>决定原因：'+esc(item.decision_reason):'')+'</p></div>';return}const actions=[];const correct=state.mode==='cost'?A.costCorrect:A.engagementCorrect,withdraw=state.mode==='cost'?A.costWithdraw:A.engagementWithdraw,history=state.mode==='cost'?A.costHistory:A.engagementHistory;if(can(item,history))actions.push('<button class="quiet" data-action="history">读取历史</button>');if(can(item,correct)&&item.state==='recorded')actions.push('<button class="quiet" data-action="correct">追加纠正</button>');if(state.mode==='engagement'&&can(item,A.engagementAssess)&&item.state==='recorded')actions.push('<button class="quiet" data-action="assess">追加评估</button>');if(can(item,withdraw)&&item.state==='recorded')actions.push('<button class="danger" data-action="withdraw">撤回</button>');const refs=state.mode==='cost'?'Project '+esc(item.project.id)+' · r'+item.project.revision:'Party '+esc(item.provider.id)+' · r'+item.provider.revision+(item.contract?'<br>Contract '+esc(item.contract.resource_id)+' · r'+item.contract.revision:'');root.innerHTML='<div class="detail-block"><div class="card-head"><div><h3>当前事实</h3><div class="badges">'+(item.allowed_actions||[]).map(x=>'<span class="badge">'+esc(x)+'</span>').join('')+'</div></div><div class="actions">'+actions.join('')+'</div></div></div><div class="detail-block"><h3>金额与内容</h3><div class="facts"><div class="fact"><small>金额</small><strong>'+money(item.amount_minor,item.currency)+'</strong></div><div class="fact"><small>状态</small><strong>'+esc(item.state)+' · r'+item.revision+'</strong></div></div><p>'+esc(state.mode==='cost'?item.description:item.scope)+'</p></div><div class="detail-block"><h3>冻结引用</h3><p class="source">'+refs+'<br>Evidence：'+(item.evidence||[]).map(x=>esc(x.display_name)+' v'+x.version).join('、')+'</p></div>'}
async function load(){if(!state.token&&!gatewayMode){$('#credentialDialog').showModal();return}state.projectID=$('#projectID').value.trim().toLowerCase();if(!state.projectID)return;try{notice('正在读取'+title()+'与服务端允许动作…');const data=await api(endpoint()+'?project_id='+encodeURIComponent(state.projectID));state.items=data.items||[];state.collectionActions=data.allowed_actions||[];state.selected=state.items.find(x=>x.id===state.selected?.id)||null;$('#projectContext').textContent=state.projectID;$('#reload').disabled=false;render();renderDetail();notice('已读取 '+state.items.length+' 条'+title()+'；页面动作已按服务端权限收敛。','ok')}catch(error){state.items=[];state.collectionActions=[];state.selected=null;render();notice(error.status===403?'当前凭证无权读取该 Project。':'读取失败：'+error.message+(error.retryable?'；依赖恢复后可显式重试。':''),'error')}}
function evidence(form){return form.elements.evidence_id.value.trim()?[{file_id:form.elements.evidence_id.value.trim(),version:Number(form.elements.evidence_version.value),slot:form.elements.evidence_slot.value.trim()}]:[]}
function configureForm(current){const f=$('#recordForm');f.reset();const correcting=!!current;f.elements.form_mode.value=correcting?'correct':'create';f.elements.record_id.value=current?.id||'';$('#formEyebrow').textContent=correcting?'追加纠正':'登记事实';$('#formTitle').textContent=(correcting?'纠正':'新建')+(state.mode==='cost'?'成本记录':'外协委托');$('#reasonField').hidden=!correcting;f.elements.reason.required=correcting;f.elements.project_revision.value=current?.project?.revision||'';const cost=state.mode==='cost';for(const id of ['costCategoryField','costDateField','distanceField','descriptionField'])$('#'+id).hidden=!cost;for(const id of ['providerIDField','providerRevisionField','scopeField','noteField','contractIDField','contractRevisionField'])$('#'+id).hidden=cost;f.elements.category.required=cost;f.elements.occurred_on.required=cost;f.elements.description.required=cost;f.elements.provider_id.required=!cost;f.elements.provider_revision.required=!cost;f.elements.scope.required=!cost;if(current){f.elements.currency.value=current.currency||'';f.elements.amount_minor.value=current.amount_minor??'';const ev=current.evidence?.[0];if(ev){f.elements.evidence_id.value=ev.file_id;f.elements.evidence_version.value=ev.version;f.elements.evidence_slot.value=ev.slot}if(cost){f.elements.category.value=current.category;f.elements.occurred_on.value=current.occurred_on;f.elements.distance_meters.value=current.distance_meters||'';f.elements.description.value=current.description}else{f.elements.provider_id.value=current.provider.id;f.elements.provider_revision.value=current.provider.revision;f.elements.scope.value=current.scope;f.elements.note.value=current.note||'';if(current.contract){f.elements.contract_id.value=current.contract.resource_id;f.elements.contract_revision.value=current.contract.revision}}}else{f.elements.currency.value='CNY';f.elements.occurred_on.value=new Date().toISOString().slice(0,10)}$('#recordDialog').showModal()}
function recordPayload(form){const correcting=form.elements.form_mode.value==='correct',base={command_id:crypto.randomUUID(),currency:form.elements.currency.value.trim().toUpperCase(),amount_minor:Number(form.elements.amount_minor.value),evidence_refs:evidence(form)};if(correcting){base.expected_revision=state.selected.revision;base.reason=form.elements.reason.value.trim()}else{base.project_ref={id:state.projectID,revision:Number(form.elements.project_revision.value)}}if(state.mode==='cost'){return {...base,category:form.elements.category.value,occurred_on:form.elements.occurred_on.value,distance_meters:Number(form.elements.distance_meters.value||0),description:form.elements.description.value.trim()}}const contractID=form.elements.contract_id.value.trim();return {...base,provider_ref:{id:form.elements.provider_id.value.trim(),revision:Number(form.elements.provider_revision.value)},scope:form.elements.scope.value.trim(),note:form.elements.note.value.trim(),...(contractID?{contract_ref:{application:'contract-ledger',resource_type:'contract',resource_id:contractID,revision:Number(form.elements.contract_revision.value)}}:{})}}
async function history(){const item=state.selected,path=endpoint()+'/'+item.id+'/history';try{const data=await api(path);$('#historyList').innerHTML=(data.items||[]).map(x=>'<div class="event"><strong>'+esc(x.event_kind)+' · revision '+x.revision+'</strong>'+esc(x.reason||'')+'<br>'+new Date(x.occurred_at).toLocaleString('zh-CN')+'</div>').join('')||'<div class="empty">没有历史。</div>'}catch(error){notice('历史读取失败：'+error.message,'error')}}
async function withdraw(){const item=state.selected,reason=prompt('请输入撤回原因');if(!reason)return;try{await api(endpoint()+'/'+item.id+'/withdrawal',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:item.revision,reason})});await load();notice('事实已显式撤回，历史仍然保留。','ok')}catch(error){notice('撤回失败：'+error.message+(error.status===409?'；请重新读取最新 revision。':''),'error')}}
async function synchronizeSuggestion(){const item=state.selected;try{await api('/api/v1/payable-suggestions/'+item.id+'/synchronization',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:item.revision,reason:'用户显式同步 Money 决定'})});await load();notice('已同步 Money 当前决定；C6 只保存目标 ID 与 revision。','ok')}catch(error){notice('同步失败：'+error.message+(error.retryable?'；Money 恢复后可使用新命令重试。':''),'error')}}
async function withdrawSuggestion(){const item=state.selected,reason=prompt('请输入撤回建议的原因');if(!reason)return;try{await api('/api/v1/payable-suggestions/'+item.id+'/withdrawal',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_revision:item.revision,reason})});await load();notice('建议已撤回；Money 与 C6 的不可变历史仍保留。','ok')}catch(error){notice('撤回建议失败：'+error.message,'error')}}
async function assessmentHistory(){try{const data=await api(endpoint()+'/'+state.selected.id+'/assessments');$('#historyList').innerHTML=(data.items||[]).map(x=>'<div class="event"><strong>评分 '+x.score+' · revision '+x.revision+'</strong>'+esc(x.reason)+'<br>'+new Date(x.occurred_at).toLocaleString('zh-CN')+'</div>').join('')||'<div class="empty">尚无评估。</div>'}catch(error){notice('评估历史读取失败：'+error.message,'error')}}
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(v=>v.classList.toggle('active',v.id===b.dataset.view))});$$('[data-go]').forEach(b=>b.onclick=()=>$('.nav[data-view="'+b.dataset.go+'"]').click());$$('.mode').forEach(b=>b.onclick=()=>{$$('.mode').forEach(x=>x.classList.toggle('active',x===b));state.mode=b.dataset.mode;state.items=[];state.selected=null;state.collectionActions=[];render();if(state.projectID&&(state.token||gatewayMode))load()});
function configureSuggestion(){const f=$('#suggestionForm');f.reset();f.elements.due_on.value=new Date().toISOString().slice(0,10);$('#suggestionDialog').showModal()}function configureSuggestionCounterparty(){const cost=$('#suggestionForm').elements.source_type.value==='cost_entry';$('#suggestionCounterpartyID').hidden=!cost;$('#suggestionCounterpartyRevision').hidden=!cost;$('#suggestionForm').elements.counterparty_id.required=cost;$('#suggestionForm').elements.counterparty_revision.required=cost}
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=e=>{if(e.submitter?.value==='cancel')return;setCredential();setTimeout(load)};$('#projectForm').onsubmit=e=>{e.preventDefault();load()};$('#reload').onclick=load;$('#newRecord').onclick=()=>state.mode==='suggestion'?configureSuggestion():configureForm();$('#suggestionForm').elements.source_type.onchange=configureSuggestionCounterparty;
$('#recordForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const f=e.currentTarget,correcting=f.elements.form_mode.value==='correct',path=correcting?endpoint()+'/'+state.selected.id+'/corrections':endpoint();try{notice(correcting?'正在追加纠正…':'正在登记事实…');await api(path,{method:'POST',body:JSON.stringify(recordPayload(f))});$('#recordDialog').close();await load();notice(correcting?'纠正已追加，旧 revision 仍可读取。':'业务事实已登记。','ok')}catch(error){notice('提交失败：'+error.message+(error.status===409?'；请先重读最新 revision。':error.status===503?'；本次没有写入，依赖恢复后可重试。':''),'error')}};
$('#detail').onclick=async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='history')history();if(action==='correct')configureForm(state.selected);if(action==='withdraw')withdraw();if(action==='synchronize')synchronizeSuggestion();if(action==='suggestion-withdraw')withdrawSuggestion();if(action==='assess'){const f=$('#assessmentForm');f.reset();try{const data=await api(endpoint()+'/'+state.selected.id+'/assessments'),items=data.items||[],latest=items.reduce((revision,item)=>Math.max(revision,item.revision||0),0);f.elements.engagement_id.value=state.selected.id;f.elements.engagement_revision.value=state.selected.revision;f.dataset.assessmentRevision=String(latest);$('#assessmentDialog').showModal()}catch(error){notice('读取评估 revision 失败：'+error.message,'error')}}};
$('#assessmentForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const f=e.currentTarget;try{await api(endpoint()+'/'+f.elements.engagement_id.value+'/assessments',{method:'POST',body:JSON.stringify({command_id:crypto.randomUUID(),expected_engagement_revision:Number(f.elements.engagement_revision.value),expected_assessment_revision:Number(f.dataset.assessmentRevision||0),score:Number(f.elements.score.value),reason:f.elements.reason.value.trim()})});$('#assessmentDialog').close();await assessmentHistory();notice('外协评估已追加。','ok')}catch(error){notice('评估失败：'+error.message,'error')}};
$('#suggestionForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const f=e.currentTarget,cost=f.elements.source_type.value==='cost_entry',payload={command_id:crypto.randomUUID(),source_type:f.elements.source_type.value,source_id:f.elements.source_id.value.trim(),source_revision:Number(f.elements.source_revision.value),ledger_owner_ref:{id:f.elements.ledger_owner_id.value.trim(),revision:Number(f.elements.ledger_owner_revision.value)},due_on:f.elements.due_on.value,purpose:f.elements.purpose.value.trim(),...(cost?{counterparty_ref:{id:f.elements.counterparty_id.value.trim(),revision:Number(f.elements.counterparty_revision.value)}}:{})};try{const value=await api('/api/v1/payable-suggestions',{method:'POST',body:JSON.stringify(payload)});$('#suggestionDialog').close();await load();notice(value.state==='target_unavailable'?'建议已在 C6 留存；Money 暂不可用，可在详情中显式重试。':'建议已送达 Money，等待其独立决定。','ok')}catch(error){notice('提出建议失败：'+error.message,'error')}};
if(gatewayMode){$('#credentialState').textContent='已由 Gateway / IAM 保护';$('#openCredential').hidden=true}else{$('#credentialState').textContent=state.token?'凭证已保存在当前标签页':'尚未连接'}const query=new URLSearchParams(location.search),requested=query.get('project_id'),requestedMode=query.get('mode');if(requestedMode==='engagement'||requestedMode==='suggestion')$('.mode[data-mode="'+requestedMode+'"]').click();if(requested){$('#projectID').value=requested;$('.nav[data-view="workspace"]').click();if(state.token||gatewayMode)load()}`
